"""FM-16W: final algebra pathways and conjugate reasoning."""
import sympy as s
from calibration_bank import LEVELS,L
x,k,h=s.symbols('x k h',real=True); I=s.I; R=s.Rational
PATHS={'factor-connection':'ALG.roots-coefficients.factor-connection','symmetric-parameter':'ALG.roots-coefficients.parameter','conjugate-find':'CPX.conjugate.find','conjugate-product':'CPX.conjugate.norm-product'}
RATIONALES={
'factor-connection':['Expand numerical binomial factors.','Diagnose a coefficient sign error.','Compare coefficients of nonmonic factors.','Recover a missing factor by simultaneous coefficient comparison.','Find all ordered factor coefficients from fixed leading factors.','Classify all real factor coefficient pairs with a varying middle coefficient, including repeated factors.'],
'symmetric-parameter':['Solve a linear coefficient equation.','Recognize the discriminant condition for repeated roots.','Recover a parameter from a symmetric square sum.','Link root sum and product to a parameter constraint.','Recover a parameter from a fixed absolute root difference.','Classify positive real roots with a bounded separation and prove the parameter interval.'],
'conjugate-find':['Reflect a point in the real axis.','Distinguish conjugation from negation.','Conjugate an expanded complex expression.','Solve a real-linear equation with a conjugate.','Solve a coupled real-imaginary system with an imaginary conjugate coefficient.','Classify conjugate equations as unique, inconsistent or infinite with two parameters.'],
'conjugate-product':['Calculate a sum of squares.','Distinguish a conjugate product from a complex square.','Simplify a rational expression using the conjugate product.','Recover the imaginary component from a prescribed norm.','Use two conjugate products to reconstruct all complex numbers.','Enrichment: classify a ratio of shifted conjugate products under a fixed norm, including endpoint uniqueness.']}
def make(path,l,v):
 if path not in PATHS or l not in LEVELS or v not in (1,2,3):raise ValueError('Unknown cell')
 a,b,d=map(s.Integer,(v+1,2*v+5,v+3)); F=(x-a)*(x-b); P=a*b; S=a+b; z=a+b*I
 if path=='factor-connection':
  if l==1:
   f=[s.expand(F)];q=f'Expand (x-{a})(x-{b}).';ans=L(f[0]);steps=[f'Multiply the two brackets: x squared minus {S}x plus {P}, giving {ans}.'];hint=['Multiply every term.'];mist='Omitting the mixed terms.'
  elif l==2:
   f=[-S,P];q=f'A student claims (x-{a})(x-{b}) has middle coefficient {S} and constant {-P}. Correct both coefficients and explain.';ans=f'Middle coefficient {-S}; constant {P}.';steps=[f'The mixed terms are -{a}x and -{b}x, so their sum has coefficient {-S}.',f'Two negative constants multiply to positive {P}.'];hint=['Track both signs.'];mist='Adding the constants instead of multiplying.'
  elif l==3:
   G=(a*x-d)*(b*x+1);f=[a*b,a-b*d,-d];q=f'Expand ({a}x-{d})({b}x+1) and identify all three coefficients.';ans=L(s.expand(G));steps=[f'The leading coefficient is {a*b}.',f'The mixed coefficient is {a}-{b*d}={a-b*d}.',f'The constant is {-d}; hence {ans}.'];hint=['Do not assume the leading coefficient is one.'];mist='Using the monic root formula before normalizing.'
  elif l==4:
   G=s.expand((a*x+d)*(b*x-1));f=[b,-1];q=f'Given the polynomial identity ({a}x+{d})(u x+w)={L(G)}, find the real coefficients u,w and verify the middle term.';ans=f'u={b}, w=-1.';steps=[f'Leading coefficient comparison gives {a}u={a*b}, so u={b}.',f'Constant comparison gives {d}w={-d}, so w=-1.',f'The middle coefficient is {a*(-1)+d*b}, matching the given polynomial.'];hint=['Compare leading and constant coefficients first.'];mist='Using only one coefficient equation.'
  elif l==5:
   C=a*d+b;D=d;f=[1,d,R(a*d,b),R(b,a)];q=f'Find every ordered real pair (p,q) such that ({a}x+p)({b}x+q)={L(a*b*x*x+C*x+D)}. Prove completeness.';ans=f'(p,q)=(1,{d}) or ({L(f[2])},{L(f[3])}).';steps=[f'Compare coefficients: {b}p+{a}q={C} and pq={D}.',f'Substitute q=({C}-{b}p)/{a}; the resulting quadratic factors as {L((s.Symbol("p")-1)*(b*s.Symbol("p")-a*d))}=0.',f'Thus p=1 or {L(f[2])}; recover the corresponding q from the linear equation.',f'Both pairs satisfy the coefficient equations, and the quadratic has no other roots.'];hint=['Eliminate q using the middle coefficient.'];mist='Assuming the two leading factors make the constants unique.'
  else:
   B=2*s.sqrt(a*b*d);p=s.Symbol('p',real=True);G=b*p*p-h*p+a*d;f=[G,-B,B];q=f'For every real h, classify all ordered real pairs (p,q) for which ({a}x+p)({b}x+q)={L(a*b*x*x+h*x+d)}. Find the pairs and justify the number of distinct solutions.';ans=f'No pairs for |h|<{L(B)}; one for |h|={L(B)}; two for |h|>{L(B)}. p=(h +/- sqrt(h^2-{4*a*b*d}))/{2*b}, q=(h-{b}p)/{a}.';steps=[f'Coefficient comparison gives {b}p+{a}q=h and pq={d}.',f'Eliminate q to obtain {L(G)}=0.',f'The discriminant is h^2-{4*a*b*d}, giving boundary values +/-{L(B)}.',f'Use the quadratic formula and q=(h-{b}p)/{a}; different p values give distinct ordered pairs.',f'Every real solution of the eliminated equation satisfies both coefficient equations on substitution, so the classification is exhaustive.'];hint=['Treat p and q as unknowns, not roots of the original polynomial.','Use the discriminant of the eliminated equation.'];mist='Counting a repeated solution twice.'
 elif path=='symmetric-parameter':
  if l==1:
   f=[b];q=f'Solve {a}k+{d}={a*b+d} for k.';ans=L(b);steps=[f'Subtract {d}, then divide by {a}, giving k={b}.'];hint=['Isolate k.'];mist='Dividing only one term.'
  elif l==2:
   f=[-2*a,2*a];q=f'A student claims x^2-kx+{a*a}=0 has repeated roots only when k={2*a}. Correct the claim.';ans=f'k=+/-{2*a}.';steps=[f'The discriminant is k^2-{4*a*a}.',f'Setting it to zero gives both k={2*a} and k={-2*a}.'];hint=['Include both square roots.'];mist='Discarding the negative parameter.'
  elif l==3:
   f=[-S,S];q=f'The roots of x^2-kx+{P}=0 are real and their squared sum is {a*a+b*b}. Determine every k without finding the roots.';ans=f'k=+/-{S}.';steps=[f'Use alpha^2+beta^2=k^2-2({P}).',f'Equating gives k^2={S*S}, hence both signs.',f'The discriminant is {(a-b)**2}>0 for both values.'];hint=['Use the squared sum identity.'];mist='Treating the sum of squares as the square of the sum.'
  elif l==4:
   K=R(a,b-1);f=[K];q=f'The roots of x^2-(k+{a})x+{b}k=0 have sum equal to product. Determine k and state whether the roots are real.';D=s.simplify((K+a)**2-4*b*K);f.append(D);ans=f'k={L(K)}; '+('real' if D>=0 else 'non-real')+' roots.';steps=[f'The sum is k+{a} and product {b}k.',f'Equating yields ({b}-1)k={a}, so k={L(K)}.',f'The discriminant is {L(D)}, determining the stated root type.'];hint=['Use Vieta before solving the quadratic.'];mist='Assuming the symmetric condition guarantees real roots.'
  elif l==5:
   G=x*x-k*x+a*k+d;B=s.sqrt(b*b+4*(a*a+d));f=[2*a-B,2*a+B];q=f'The real roots of {L(G)}=0 have absolute difference {b}. Determine every k and verify that both possibilities are valid.';ans=f'k={L(2*a-B)} or {L(2*a+B)}.';steps=[f'The squared root difference is k^2-4({a}k+{d}).',f'Equate this to {b*b} and complete the square: (k-{2*a})^2={b*b+4*(a*a+d)}.',f'The two values are {ans}; each gives discriminant {b*b}>0 and the required difference.'];hint=['The squared difference equals the discriminant for a monic quadratic.'];mist='Choosing only the positive square-root branch.'
  else:
   G=x*x-k*x+a*k+d;B=2*a+2*s.sqrt(a*a+d);U=2*a+s.sqrt(4*(a*a+d)+h*h);f=[B,U];q=f'For each real h, determine all real k for which {L(G)}=0 has two strictly positive real roots (counting multiplicity) with absolute difference at most h. Prove necessity and sufficiency.';ans=f'None for h<0; otherwise {L(B)} <= k <= {L(U)}.';steps=['A nonnegative absolute difference cannot be at most a negative h.',f'Positive roots require positive sum k and positive product {a}k+{d}; the latter follows from k>0.',f'The real-root and separation constraints give 0 <= (k-{2*a})^2-{4*(a*a+d)} <= h^2.',f'The negative branch k <= {L(2*a-2*s.sqrt(a*a+d))} is strictly negative, so it is excluded.',f'The positive branch gives {ans}. Every k in that closed interval has positive sum and product and a nonnegative discriminant at most h^2, so both roots are positive with the required separation. At h=0 the interval collapses to a repeated positive root.'];hint=['Combine the sign constraints with a two-sided discriminant inequality.'];mist='Keeping the negative branch of the squared inequality.'
 elif path=='conjugate-find':
  if l==1:
   f=[a-b*I];q=f'Reflect the point ({a},{b}) in the real axis of an Argand diagram and give its complex coordinate.';ans=L(f[0]);steps=[f'The real coordinate stays {a}, while the imaginary coordinate becomes {-b}; hence {ans}.'];hint=['Reflect vertically.'];mist='Changing both signs.'
  elif l==2:
   f=[a+b*I];q=f'A student says the conjugate of {L(a-b*I)} is {L(-a+b*I)}. Correct the claim and explain.';ans=L(f[0]);steps=['Conjugation leaves the real part unchanged and reverses only the imaginary part.',f'The correct value is {ans}.'];hint=['Conjugation is not negation.'];mist='Negating the whole number.'
  elif l==3:
   Z=(a+I)*(b-d*I);f=[s.conjugate(s.expand(Z))];q=f'Expand ({a}+i)({b}-{d}i) and then find its conjugate in standard form.';ans=L(f[0]);steps=[f'Expand using i squared = -1 to obtain {L(s.expand(Z))}.',f'Reverse the imaginary part only to obtain {ans}.'];hint=['Simplify before conjugating.'];mist='Conjugating only one factor.'
  elif l==4:
   Z=R(b,1+a)+R(d,1-a)*I;f=[Z];q=f'Find z satisfying z+{a} conjugate(z)={L(b+d*I)}. Verify the answer.';ans=L(Z);steps=[f'Write z=u+iv; comparison gives ({1+a})u={b} and ({1-a})v={d}.',f'Both coefficients are nonzero, so z={ans}.',f'Substitution gives {L(b+d*I)} as required.'];hint=['Separate real and imaginary parts.'];mist='Treating conjugate(z) as z.'
  elif l==5:
   u=R(b-a*d,1-a*a);w=R(d-a*b,1-a*a);Z=u+I*w;f=[Z];q=f'Solve z+{a}i conjugate(z)={L(b+d*I)}. Prove uniqueness.';ans=L(Z);steps=[f'Writing z=u+iv gives u+{a}v={b}, {a}u+v={d}.',f'The coefficient determinant is {1-a*a}, nonzero.',f'Solve to obtain u={L(u)}, v={L(w)}, hence {ans}.',f'Substitution verifies both equations; the nonzero determinant ensures uniqueness.'];hint=['Multiply i by the conjugate before comparing components.'];mist='Missing the real term from i times -iv.'
  else:
   Z=a/(1+k)+I*h/(1-k);f=[Z,-1,1];q=f'For every real pair (k,h), classify the solutions of z+k conjugate(z)={L(a+I*h)}. Find all solutions including exceptional cases.';ans=f'For k not equal to +/-1, z={L(Z)} uniquely. At k=1, h=0 gives z={L(a/2)}+iv for all real v; otherwise none. At k=-1 there is no solution.';steps=[f'Write z=u+iv. Then (1+k)u={a} and (1-k)v=h.',f'If neither coefficient vanishes, divide to obtain the unique z={L(Z)}.',f'At k=1 the first equation forces u={L(a/2)} and the second requires h=0; v is then arbitrary.',f'At k=-1 the first equation requires 0={a}, impossible.', 'The cases exhaust every real k; substituting the listed solutions verifies the original equation.'];hint=['Do not divide by 1+k or 1-k before treating zero coefficients.'];mist='Losing the infinite family by dividing by zero.'
 else:
  N=a*a+b*b
  if l==1:
   f=[N];q=f'Calculate the sum of the squares of {a} and {-b}.';ans=L(N);steps=[f'Both squares are nonnegative; their sum is {ans}.'];hint=['Square the negative value before adding.'];mist='Keeping a negative square.'
  elif l==2:
   f=[N];q=f'A student says the product of {L(z)} and its conjugate equals its square. Calculate the conjugate product and explain.';ans=L(N);steps=[f'The conjugate is {L(s.conjugate(z))}.',f'The product is the difference of squares: {a} squared plus {b} squared = {N}, a positive real number.'];hint=['Use opposite imaginary signs.'];mist='Squaring the original number.'
  elif l==3:
   Z=s.expand((d+I)*s.conjugate(z))/N;f=[Z];q=f'Use the conjugate product to express ({d}+i)/({a}+{b}i) in standard form.';ans=L(Z);steps=[f'Multiply numerator and denominator by {L(s.conjugate(z))}.',f'The denominator is {N}, and the expanded numerator is {L(s.expand((d+I)*s.conjugate(z)))}.',f'Dividing gives {ans}.'];hint=['Multiply top and bottom by the denominator conjugate.'];mist='Conjugating the numerator instead.'
  elif l==4:
   f=[-b,b];q=f'Let z={a}+iy for real y. Given z conjugate(z)={N}, find every y and explain why there are two.';ans=f'y=+/-{b}.';steps=[f'The conjugate product is {a*a}+y^2.',f'Equate to {N} to obtain y^2={b*b}; both signs satisfy the equation.'];hint=['The product contains y squared, not y.'];mist='Keeping only the positive imaginary part.'
  elif l==5:
   M=(a+d)**2+b*b;f=[a-b*I,a+b*I];q=f'Find all complex z satisfying z conjugate(z)={N} and (z+{d}) conjugate(z+{d})={M}. Prove completeness.';ans=f'z={L(f[0])} or {L(f[1])}.';steps=[f'Write z=u+iv. The equations are u^2+v^2={N}, (u+{d})^2+v^2={M}.',f'Subtract to get {2*d}u+{d*d}={M-N}; hence u={a}.',f'Back-substitution gives v^2={b*b}, so both signs occur.',f'Both values satisfy both product equations; no other u or v is possible.'];hint=['Subtract the norm equations to cancel the squares.'];mist='Losing one of the conjugate pair.'
  else:
   C=a*a+b*b;lo=R((b-a)**2,(b+a)**2);hi=1/lo;U=C*(h-1)/(2*a*(h+1));f=[U,lo,hi];q=f'Let z conjugate(z)={b*b}. For every real h classify and find all z satisfying (z+{a}) conjugate(z+{a}) / ((z-{a}) conjugate(z-{a}))=h. Account for all endpoints. (Enrichment.)';ans=f'None outside [{L(lo)}, {L(hi)}]; one at either endpoint; two inside. Within the interval let u={L(U)}; then z=u +/- i sqrt({b*b}-u^2).';steps=[f'Write z=u+iv with u^2+v^2={b*b}. Since {b}>{a}, neither z+{a} nor z-{a} is zero; the ratio is positive.',f'Expand conjugate products: h=({C}+{2*a}u)/({C}-{2*a}u).',f'Solve for u={L(U)}; h=-1 is already excluded by positivity.',f'The ratio is strictly increasing for -{b} <= u <= {b}: its positive denominator decreases while its positive numerator increases. Its endpoint values are {L(lo)} and {L(hi)}.',f'For each h in this closed interval the unique u lies in [-{b},{b}]; v^2={b*b}-u^2 gives two distinct signs in the interior and one zero at either endpoint.', 'Substitution verifies every solution and the monotonicity and norm constraints exclude all others.'];hint=['Use the known norm to simplify both shifted products.','Apply the real-part bounds from the fixed norm.'];mist='Allowing negative ratios or counting v=0 twice.'
 return dict(path=path,focus_skill=PATHS[path],tier=l,variant=v,assessment_role='prerequisite_bridge' if l==1 else 'concept_diagnostic' if l==2 else 'direct_focus_task',question_latex=q,final_answer_latex=ans,worked_solution_latex=steps,progressive_hints=hint,rubric=[dict(marks=1,criterion=e) for e in steps],facts=[str(e) for e in f],likely_mistake=mist,origin='original',examination_source=None,difficulty_status='editorial_design_teacher_pending',demand_rationale=RATIONALES[path][l-1])
